non_compliant_examples.rust_code:
fn main() {
    let bits : u32 = 61;
    let shifts = vec![-1, 4, 40];

    for sh in shifts {
        println!("{bits} << {sh} = {:?}", bits << sh);
    }
}

fn main() {
    let bits: u32 = 61;
    let shifts = vec![-1, 0, 4, 40];

    for sh in shifts {
        if sh >= 0 && sh < 32 {
            println!("{bits} << {sh} = {}", bits << sh);
        }
     }
}

fn main() {
    let bits : u32 = 61;
    let shifts = vec![4, 40];

    for sh in shifts {
        println!("{bits} << {sh} = {:?}", bits.wrapping_shl(sh));
    }
}

fn main() {
    let bits : u32 = 61;
    let shifts = vec![4, 40];

    for sh in shifts {
        println!("{bits} << {sh} = {:?}", bits.unbounded_shr(sh));
    }
}

fn main() {
    let bits: u32 = 61;
    let shifts = vec![4, 40];

    for sh in shifts {
        let (result, overflowed) = bits.overflowing_shl(sh);
        if overflowed {
            println!("{bits} << {sh} shift too large");
        } else {
            println!("{bits} << {sh} = {result}");
        }
    }
}

compliant_examples.rust_code:
fn main() {
    let bits : u32 = 61;
    // let shifts = vec![-1, 4, 40];
    //                    ^--- Compiler rejects negative shifts
    let shifts = vec![4, 40];

    for sh in shifts {
        println!("{bits} << {sh} = {:?}", bits.checked_shl(sh));
    }
}
